$helpers=@'
const ROOT='oscarhiishanmin26@gmail.com';const b64=(b:Uint8Array)=>btoa(String.fromCharCode(...b));async function hash(password:string,salt?:string){const s=salt?Uint8Array.from(atob(salt),c=>c.charCodeAt(0)):crypto.getRandomValues(new Uint8Array(16)),key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']),bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:s,iterations:120000,hash:'SHA-256'},key,256);return{salt:b64(s),value:b64(new Uint8Array(bits))}}async function account(e:Env,email:string){return e.DB.prepare('SELECT email,role,password_hash passwordHash,salt,must_change mustChange,active FROM admins WHERE email=?').bind(email.toLowerCase()).first<any>()}
'@
