$old=@'
if(p==='/api/admin/login'&&r.method==='POST'){const x=await data(r),row=await e.DB.prepare("SELECT value FROM settings WHERE key='admin_email'").first<{value:string}>();if(!row||x.email?.toLowerCase()!==row.value.toLowerCase()||x.password!==e.ADMIN_TOKEN)return J({error:'Email 或密碼錯誤'},401);const id=crypto.randomUUID(),expires=new Date(Date.now()+288e5).toISOString();await e.DB.prepare('INSERT INTO admin_sessions(id,email,expires_at) VALUES(?,?,?)').bind(id,row.value,expires).run();return J({email:row.value},200,{'set-cookie':secureCookie(id)})}
'@
$new=@'
if(p==='/api/admin/login'&&r.method==='POST'){const x=await data(r),email=String(x.email||'').trim().toLowerCase();let a=await account(e,email);if(!a&&email===ROOT&&x.password===e.ADMIN_TOKEN){const h=await hash(x.password);await e.DB.prepare('INSERT INTO admins(email,role,password_hash,salt,must_change)VALUES(?,?,?,?,0)').bind(ROOT,'superadmin',h.value,h.salt).run();a=await account(e,email)}if(!a||!a.active)return J({error:'Email 或密碼錯誤'},401);const h=await hash(String(x.password||''),a.salt);if(h.value!==a.passwordHash)return J({error:'Email 或密碼錯誤'},401);const id=crypto.randomUUID(),expires=new Date(Date.now()+288e5).toISOString();await e.DB.prepare('INSERT INTO admin_sessions(id,email,expires_at)VALUES(?,?,?)').bind(id,email,expires).run();return J({email,role:a.role,mustChange:!!a.mustChange},200,{'set-cookie':secureCookie(id)})}
if(p==='/api/admin/forgot'&&r.method==='POST'){const x=await data(r),email=String(x.email||'').trim().toLowerCase();if(await account(e,email)&&!await e.DB.prepare("SELECT 1 FROM admin_reset_requests WHERE email=? AND status='pending'").bind(email).first())await e.DB.prepare('INSERT INTO admin_reset_requests(id,email)VALUES(?,?)').bind(crypto.randomUUID(),email).run();return J({ok:true,message:'若帳號存在，重設申請已送給最高管理員'})}
'@
