$routes=@'
if(p==='/api/admin/change-password'&&r.method==='POST'){const s=await session(r,e),x=await data(r),a=await account(e,s!.email),old=await hash(String(x.currentPassword||''),a.salt);if(old.value!==a.passwordHash)return J({error:'目前密碼不正確'},400);if(String(x.newPassword||'').length<8)return J({error:'新密碼至少需要 8 個字元'},400);const h=await hash(x.newPassword);await e.DB.prepare('UPDATE admins SET password_hash=?,salt=?,must_change=0 WHERE email=?').bind(h.value,h.salt,s!.email).run();return J({ok:true})}
if(p==='/api/admin/admins'&&r.method==='POST'){const s=await session(r,e),me=await account(e,s!.email);if(me?.role!=='superadmin')return J({error:'只有最高管理員可以新增管理員'},403);const x=await data(r),email=String(x.email||'').trim().toLowerCase();if(!email.includes('@'))return J({error:'Email 格式不正確'},400);const h=await hash('000000');await e.DB.prepare('INSERT INTO admins(email,role,password_hash,salt,must_change)VALUES(?,?,?,?,1)').bind(email,'admin',h.value,h.salt).run();return J({ok:true},201)}
const adm=p.match(/^\/api\/admin\/admins\/(.+)$/);if(adm&&r.method==='DELETE'){const s=await session(r,e),me=await account(e,s!.email),email=decodeURIComponent(adm[1]).toLowerCase();if(me?.role!=='superadmin')return J({error:'權限不足'},403);if(email===ROOT)return J({error:'最高管理員不能刪除'},400);await e.DB.prepare('UPDATE admins SET active=0 WHERE email=?').bind(email).run();return J({ok:true})}
const reset=p.match(/^\/api\/admin\/resets\/([^/]+)$/);if(reset&&r.method==='POST'){const s=await session(r,e),me=await account(e,s!.email);if(me?.role!=='superadmin')return J({error:'權限不足'},403);const row=await e.DB.prepare("SELECT email FROM admin_reset_requests WHERE id=? AND status='pending'").bind(reset[1]).first<any>();if(!row)return J({error:'申請不存在'},404);const h=await hash('000000');await e.DB.batch([e.DB.prepare('UPDATE admins SET password_hash=?,salt=?,must_change=1 WHERE email=?').bind(h.value,h.salt,row.email),e.DB.prepare("UPDATE admin_reset_requests SET status='resolved',resolved_at=CURRENT_TIMESTAMP WHERE id=?").bind(reset[1])]);return J({ok:true})}
